export PATH=/persist/dart-sdk/bin:/persist/dotnet:/persist/kotlinc/bin:/persist/swift/usr/bin:$PATH
export DOTNET_CLI_TELEMETRY_OPTOUT=1
export DOTNET_NOLOGO=1
